//! Host-level privacy network provisioning — OVS switching fabric only.
//
// Current architecture (Artix Linux + s6 + Incus + rovs):
// - Host runs ovsbr0 via OVSDB (datapath=system or netdev for AF_XDP)
// - All privacy services (Xray, mail) run inside Incus containers
// - Containers have NO host interface — they communicate via Unix sockets
//   through OVS internal ports using OpenFlow routing
// - Xray ingress lives in wg-xray Incus container, NOT on host
// - OpenFlow controller (also in wg-xray container) drives forwarding
// - priv_* internal ports are created by ovs-attach-ports.sh

use anyhow::{Context, Result};
use op_network::{openflow::OpenFlowClient, OvsdbDbusClient};
use std::path::Path;
use tracing::{info, warn};

const DEFAULT_BRIDGE: &str = "ovsbr0";
const DEFAULT_PRIVACY_PORTS: &[&str] = &[
    "gbr_xray",
    "gbr_warp",
    "gbr_wg",
    "ovsbr0-mgmt",
    "ovsbr0-sock",
];
const DEFAULT_MGMT_CIDR: &str = "10.200.0.1/24"; // Xray ingress IP (inside wg-xray container)
const DEFAULT_OPENFLOW_CONTROLLER: &str = "10.200.0.1:6653"; // Controller inside wg-xray
const DEFAULT_DATAPATH_TYPE: &str = "system";
const DEFAULT_FAIL_MODE: &str = "standalone";

#[derive(Debug, Clone)]
pub struct PrivacyNetworkHostConfig {
    pub bridge_name: String,
    pub privacy_ports: Vec<String>,
    pub management_cidr: String,
    pub openflow_controller: String,
    pub xray_ingress_ip: String,
    pub datapath_type: String,
    pub fail_mode: String,
}

impl PrivacyNetworkHostConfig {
    pub fn from_env() -> Self {
        Self {
            bridge_name: std::env::var("PRIVACY_BRIDGE_NAME")
                .unwrap_or_else(|_| DEFAULT_BRIDGE.to_string()),
            privacy_ports: std::env::var("PRIVACY_PORTS")
                .map(|s| s.split(',').map(|s| s.trim().to_string()).collect())
                .unwrap_or_else(|_| {
                    DEFAULT_PRIVACY_PORTS
                        .iter()
                        .map(|&s| s.to_string())
                        .collect()
                }),
            management_cidr: std::env::var("PRIVACY_MGMT_CIDR")
                .unwrap_or_else(|_| DEFAULT_MGMT_CIDR.to_string()),
            openflow_controller: std::env::var("PRIVACY_OPENFLOW_CONTROLLER")
                .unwrap_or_else(|_| DEFAULT_OPENFLOW_CONTROLLER.to_string()),
            xray_ingress_ip: std::env::var("XRAY_INGRESS_IP")
                .unwrap_or_else(|_| "10.200.0.1".to_string()),
            datapath_type: std::env::var("PRIVACY_DATAPATH_TYPE")
                .unwrap_or_else(|_| DEFAULT_DATAPATH_TYPE.to_string()),
            fail_mode: std::env::var("PRIVACY_FAIL_MODE")
                .unwrap_or_else(|_| DEFAULT_FAIL_MODE.to_string()),
        }
    }
}

/// Ensure host privacy network topology exists for wgcf architecture.
///
/// This is called during magic link verification to ensure the network
/// is ready for new users.
pub async fn ensure_host_privacy_network() -> Result<()> {
    let cfg = PrivacyNetworkHostConfig::from_env();
    ensure_host_privacy_network_with_config(&cfg).await
}

async fn ensure_host_privacy_network_with_config(cfg: &PrivacyNetworkHostConfig) -> Result<()> {
    info!(
        "Ensuring OVS privacy fabric: bridge={} ports={:?}",
        cfg.bridge_name, cfg.privacy_ports
    );

    let ovs = OvsdbDbusClient::new();

    // Verify OVSDB connectivity
    ovs.list_dbs()
        .await
        .context("Open vSwitch DB is unavailable; cannot provision privacy network")?;

    // The bridge should be created by netplan/op-ovsbr0-setup, but ensure it exists
    if !ovs
        .bridge_exists(&cfg.bridge_name)
        .await
        .context("Failed to check bridge existence")?
    {
        info!("Bridge {} not found, creating via OVSDB", cfg.bridge_name);
        ovs.create_bridge(&cfg.bridge_name)
            .await
            .with_context(|| format!("Failed to create OVS bridge '{}'", cfg.bridge_name))?;
    }

    // Configure bridge for controller-driven forwarding. AF_XDP cutover sets
    // PRIVACY_DATAPATH_TYPE=netdev so this path does not undo the datapath.
    info!(
        "Configuring {} datapath_type={} fail_mode={}",
        cfg.bridge_name, cfg.datapath_type, cfg.fail_mode
    );
    ovs.set_bridge_property(&cfg.bridge_name, "datapath_type", &cfg.datapath_type)
        .await
        .with_context(|| format!("Failed to set bridge datapath_type={}", cfg.datapath_type))?;
    ovs.set_bridge_property(&cfg.bridge_name, "fail_mode", &cfg.fail_mode)
        .await
        .with_context(|| format!("Failed to set bridge fail_mode={}", cfg.fail_mode))?;

    let existing_ports = ovs
        .list_bridge_ports(&cfg.bridge_name)
        .await
        .context("Failed to list bridge ports")?;

    // NOTE: wgcf/Xray run inside Incus containers (wg-xray), not as host interfaces.
    // Container traffic reaches the bridge via Unix sockets + OpenFlow routing.
    // Do NOT attach wgcf as a host port — it does not exist on the host.

    // Ensure all privacy internal ports exist (created by ovs-attach-ports.sh)
    for port in &cfg.privacy_ports {
        if !existing_ports.iter().any(|p| p == port) {
            ovs.add_port_with_type(&cfg.bridge_name, port, Some("internal"))
                .await
                .with_context(|| format!("Failed to add internal port '{}'", port))?;
            info!("Added internal port: {}", port);
        }
    }

    // Bring up host bridge only (containers have no host interfaces)
    if Path::new(&format!("/sys/class/net/{}", cfg.bridge_name)).exists() {
        op_network::rtnetlink::link_up(&cfg.bridge_name)
            .await
            .with_context(|| format!("Failed to bring up interface {}", cfg.bridge_name))?;
    }

    // Bring up privacy internal ports
    for port in &cfg.privacy_ports {
        if Path::new(&format!("/sys/class/net/{}", port)).exists() {
            op_network::rtnetlink::link_up(port)
                .await
                .with_context(|| format!("Failed to bring up port {}", port))?;
        }
    }

    // Verify Xray ingress is available on the management IP
    // NOTE: Xray runs inside the wg-xray Incus container, not on the host.
    // The management IP is reachable through OVS internal ports + OpenFlow.
    info!(
        "Privacy network ready. Xray ingress (in wg-xray container) should be listening on {}",
        cfg.xray_ingress_ip
    );

    // Probe OpenFlow controller if available
    // NOTE: Controller runs inside wg-xray container, reachable via OVS tunnel.
    if let Ok(controller_addr) = cfg.openflow_controller.parse::<std::net::SocketAddr>() {
        match OpenFlowClient::connect(controller_addr).await {
            Ok(_) => info!("OpenFlow controller reachable (via container path)"),
            Err(e) => warn!("OpenFlow controller not ready yet: {}", e),
        }
    }

    info!("OVS privacy fabric provisioning complete (containerized services via Unix sockets)");
    Ok(())
}

use anyhow::{anyhow, bail, Context, Result};
use base64::Engine as _;
use chrono::Utc;
use ring::hkdf;
use serde::{Deserialize, Serialize};

use crate::users::PrivacyUser;

const DEFAULT_INGRESS_PORT: &str = "ovsbr0-sock";
const DEFAULT_NEXT_HOP: &str = "gbr_wg";
const ROUTE_HKDF_INFO: &[u8] = b"op-dbus/privacy-route/v1";

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PrivacyRoutesState {
    #[serde(default)]
    pub routes: Vec<PrivacyRoute>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct PrivacyRoute {
    pub name: String,
    pub route_id: String,
    pub user_id: String,
    pub email: String,
    pub wireguard_public_key: String,
    pub assigned_ip: String,
    pub selector_ip: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub container_name: Option<String>,
    pub ingress_port: String,
    pub next_hop: String,
    pub enabled: bool,
    pub created_at: String,
    pub updated_at: String,
}

struct RouteIdKeyLen;

impl hkdf::KeyType for RouteIdKeyLen {
    fn len(&self) -> usize {
        32
    }
}

pub async fn publish_user_privacy_route(
    user: &PrivacyUser,
    container_name: Option<&str>,
) -> Result<String> {
    let route_id = derive_route_id(&user.wg_public_key)?;
    let mut state = crate::state_manager_client::query_plugin_state("privacy_routes")
        .await?
        .unwrap_or(PrivacyRoutesState { routes: Vec::new() });
    upsert_route(
        &mut state,
        PrivacyRoute::from_user(user, route_id.clone(), container_name),
    );
    crate::state_manager_client::apply_plugin_state("privacy_routes", &state).await?;

    Ok(route_id)
}

fn upsert_route(state: &mut PrivacyRoutesState, route: PrivacyRoute) {
    match state
        .routes
        .iter_mut()
        .find(|existing| existing.route_id == route.route_id)
    {
        Some(existing) => {
            let created_at = existing.created_at.clone();
            *existing = route;
            existing.created_at = created_at;
        }
        None => state.routes.push(route),
    }

    state.routes.sort_by(|a, b| a.route_id.cmp(&b.route_id));
}

pub fn derive_route_id(wg_public_key: &str) -> Result<String> {
    let shared_secret = std::env::var("PRIVACY_ROUTE_SHARED_SECRET")
        .context("PRIVACY_ROUTE_SHARED_SECRET is required for privacy route derivation")?;
    if shared_secret.trim().is_empty() {
        bail!("PRIVACY_ROUTE_SHARED_SECRET must not be empty");
    }

    let public_key_bytes = base64::engine::general_purpose::STANDARD
        .decode(wg_public_key.trim())
        .with_context(|| format!("invalid WireGuard public key '{}'", wg_public_key))?;
    if public_key_bytes.len() != 32 {
        bail!(
            "WireGuard public key must decode to 32 bytes, got {}",
            public_key_bytes.len()
        );
    }

    let salt = hkdf::Salt::new(hkdf::HKDF_SHA256, shared_secret.as_bytes());
    let prk = salt.extract(&public_key_bytes);
    let okm = prk
        .expand(&[ROUTE_HKDF_INFO], RouteIdKeyLen)
        .map_err(|_| anyhow!("failed to expand HKDF route ID"))?;
    let mut route_id = [0u8; 32];
    okm.fill(&mut route_id)
        .map_err(|_| anyhow!("failed to derive HKDF route ID bytes"))?;
    Ok(hex::encode(route_id))
}

impl PrivacyRoute {
    fn from_user(user: &PrivacyUser, route_id: String, container_name: Option<&str>) -> Self {
        let now = Utc::now().to_rfc3339();
        Self {
            name: route_id.clone(),
            route_id,
            user_id: user.id.clone(),
            email: user.email.clone(),
            wireguard_public_key: user.wg_public_key.clone(),
            assigned_ip: user.assigned_ip.clone(),
            selector_ip: selector_ip(&user.assigned_ip),
            container_name: container_name.map(ToOwned::to_owned),
            ingress_port: std::env::var("PRIVACY_ROUTE_INGRESS_PORT")
                .unwrap_or_else(|_| DEFAULT_INGRESS_PORT.to_string()),
            next_hop: std::env::var("PRIVACY_ROUTE_NEXT_HOP")
                .unwrap_or_else(|_| DEFAULT_NEXT_HOP.to_string()),
            enabled: true,
            created_at: now.clone(),
            updated_at: now,
        }
    }
}

fn selector_ip(cidr: &str) -> String {
    cidr.split('/').next().unwrap_or(cidr).to_string()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_route_id_is_deterministic() {
        std::env::set_var("PRIVACY_ROUTE_SHARED_SECRET", "test-shared-secret");
        let key = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=";
        let a = derive_route_id(key).expect("derive a");
        let b = derive_route_id(key).expect("derive b");
        assert_eq!(a, b);
        assert_eq!(a.len(), 64);
    }

    #[test]
    fn test_selector_ip_strips_prefix() {
        assert_eq!(selector_ip("10.100.0.2/32"), "10.100.0.2");
        assert_eq!(selector_ip("10.100.0.2"), "10.100.0.2");
    }
}

//! Per-user privacy container publication.
//!
//! Registration/verification flows publish desired Incus state through
//! `org.opdbus.StateManager` instead of shelling out to `incus` directly.

use anyhow::{bail, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use tracing::{debug, info};

use crate::privacy_routes::derive_route_id;
use crate::users::PrivacyUser;

const DEFAULT_CONTAINER_IMAGE: &str = "images:alpine/3.19";
const DEFAULT_NAME_PREFIX: &str = "privacy-user-";
const DEFAULT_DEVICE_NAME: &str = "privacy0";

#[derive(Debug, Clone)]
pub struct PrivacyContainerConfig {
    pub image: String,
    pub name_prefix: String,
    pub device_name: String,
    pub storage_pool: Option<String>,
    pub attach_bridged_nic: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct IncusState {
    #[serde(default)]
    instances: Vec<IncusInstance>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct IncusInstance {
    name: String,
    status: String,
    #[serde(rename = "type")]
    instance_type: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    image: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    storage_pool: Option<String>,
    #[serde(default)]
    profiles: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    config: Option<HashMap<String, String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    devices: Option<HashMap<String, HashMap<String, String>>>,
}

impl PrivacyContainerConfig {
    pub fn from_env() -> Self {
        Self {
            image: std::env::var("PRIVACY_CONTAINER_IMAGE")
                .unwrap_or_else(|_| DEFAULT_CONTAINER_IMAGE.to_string()),
            name_prefix: std::env::var("PRIVACY_CONTAINER_PREFIX")
                .unwrap_or_else(|_| DEFAULT_NAME_PREFIX.to_string()),
            device_name: std::env::var("PRIVACY_CONTAINER_DEVICE")
                .unwrap_or_else(|_| DEFAULT_DEVICE_NAME.to_string()),
            storage_pool: std::env::var("PRIVACY_CONTAINER_STORAGE_POOL")
                .ok()
                .map(|v| v.trim().to_string())
                .filter(|v| !v.is_empty()),
            attach_bridged_nic: std::env::var("PRIVACY_CONTAINER_ATTACH_BRIDGED_NIC")
                .ok()
                .map(|value| {
                    let value = value.trim().to_ascii_lowercase();
                    value == "1" || value == "true" || value == "yes"
                })
                .unwrap_or(true),
        }
    }
}

/// Ensure an Incus container is represented in desired state and running.
///
/// Idempotent: existing instances are updated in place.
pub async fn ensure_user_container(user: &PrivacyUser) -> Result<String> {
    let cfg = PrivacyContainerConfig::from_env();
    ensure_user_container_with_config(user, &cfg).await
}

async fn ensure_user_container_with_config(
    user: &PrivacyUser,
    cfg: &PrivacyContainerConfig,
) -> Result<String> {
    if !cfg.attach_bridged_nic && cfg.storage_pool.is_none() {
        bail!(
            "PRIVACY_CONTAINER_STORAGE_POOL is required when provisioning Incus containers without a bridged NIC"
        );
    }

    let container_name = container_name_for_user(&user.id, &cfg.name_prefix);
    let route_id = derive_route_id(&user.wg_public_key)?;
    debug!(
        "Publishing privacy container '{}' for user {} via StateManager",
        container_name, user.id
    );

    let mut state = crate::state_manager_client::query_plugin_state("incus")
        .await?
        .unwrap_or(IncusState {
            instances: Vec::new(),
        });
    upsert_instance(
        &mut state,
        desired_instance(user, &container_name, &route_id, cfg),
    );
    crate::state_manager_client::apply_plugin_state("incus", &state).await?;

    info!(
        "Privacy container '{}' is published and running for user {}",
        container_name, user.id
    );
    Ok(container_name)
}

fn desired_instance(
    user: &PrivacyUser,
    container_name: &str,
    route_id: &str,
    cfg: &PrivacyContainerConfig,
) -> IncusInstance {
    let devices = if cfg.attach_bridged_nic {
        let bridge =
            std::env::var("PRIVACY_CONTAINER_BRIDGE").unwrap_or_else(|_| "ovsbr0".to_string());
        Some(HashMap::from([(
            cfg.device_name.clone(),
            HashMap::from([
                ("type".to_string(), "nic".to_string()),
                ("nictype".to_string(), "bridged".to_string()),
                ("parent".to_string(), bridge),
            ]),
        )]))
    } else {
        None
    };

    IncusInstance {
        name: container_name.to_string(),
        status: "Running".to_string(),
        instance_type: "container".to_string(),
        image: Some(cfg.image.clone()),
        storage_pool: cfg.storage_pool.clone(),
        profiles: Vec::new(),
        config: Some(HashMap::from([
            ("user.opdbus.user_id".to_string(), user.id.clone()),
            ("user.opdbus.email".to_string(), user.email.clone()),
            (
                "user.opdbus.assigned_ip".to_string(),
                user.assigned_ip.clone(),
            ),
            (
                "user.opdbus.wireguard_public_key".to_string(),
                user.wg_public_key.clone(),
            ),
            ("user.opdbus.route_id".to_string(), route_id.to_string()),
        ])),
        devices,
    }
}

fn upsert_instance(state: &mut IncusState, instance: IncusInstance) {
    match state
        .instances
        .iter_mut()
        .find(|existing| existing.name == instance.name)
    {
        Some(existing) => *existing = instance,
        None => state.instances.push(instance),
    }
    state.instances.sort_by(|a, b| a.name.cmp(&b.name));
}

fn container_name_for_user(user_id: &str, name_prefix: &str) -> String {
    let mut prefix = normalize_prefix(name_prefix);
    if !prefix.ends_with('-') {
        prefix.push('-');
    }

    let suffix = user_suffix(user_id);
    let mut full_name = format!("{}{}", prefix, suffix);
    if full_name.len() > 63 {
        full_name.truncate(63);
        while full_name.ends_with('-') {
            full_name.pop();
        }
    }
    full_name
}

fn normalize_prefix(prefix: &str) -> String {
    let mut out: String = prefix
        .chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '-')
        .map(|c| c.to_ascii_lowercase())
        .collect();

    if out.is_empty() {
        out = DEFAULT_NAME_PREFIX.trim_end_matches('-').to_string();
    }

    out
}

fn user_suffix(user_id: &str) -> String {
    let suffix: String = user_id
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .take(12)
        .collect();

    if suffix.is_empty() {
        "user".to_string()
    } else {
        suffix
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generates_container_name_from_uuid() {
        let name = container_name_for_user("f7f95f64-5f65-4c2d-a47d-4f9c1122af10", "privacy-user-");
        assert_eq!(name, "privacy-user-f7f95f645f65");
    }

    #[test]
    fn sanitizes_non_alnum_characters() {
        let name = container_name_for_user("A B:C", "My Prefix!");
        assert_eq!(name, "myprefix-abc");
    }

    #[test]
    fn falls_back_to_default_prefix_and_suffix() {
        let name = container_name_for_user("----", "");
        assert_eq!(name, "privacy-user-user");
    }

    #[test]
    fn desired_instance_publishes_route_without_bridged_nic_by_default() {
        let user = PrivacyUser {
            id: "user-1".to_string(),
            email: "user@example.com".to_string(),
            email_verified: true,
            created_at: chrono::Utc::now(),
            wg_public_key: "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=".to_string(),
            wg_private_key_encrypted: "secret".to_string(),
            assigned_ip: "10.100.0.2/32".to_string(),
            privacy_quota_bytes: 1,
            privacy_quota_used_bytes: 0,
            privacy_container_name: None,
            privacy_route_id: None,
            privacy_network_connected: false,
            privacy_network_connected_at: None,
            google_id: None,
            google_email: None,
            api_credentials: None,
        };
        let cfg = PrivacyContainerConfig::from_env();
        let instance = desired_instance(&user, "privacy-user-user1", "route-a", &cfg);
        assert_eq!(
            instance.config.as_ref().unwrap()["user.opdbus.route_id"],
            "route-a"
        );
        assert!(instance.devices.is_none());
        assert!(instance.profiles.is_empty());
    }
}
